insert into platform_modules (code,title,is_active) values ('30-loan-relief','بخشودگی و امهال مطالبات تسهیلات',true) on conflict (code) do update set title=excluded.title,is_active=true;
insert into module_field_definitions(module_id,field_key,title,field_type,required,sort_order,options)
select m.id,v.field_key,v.title,v.field_type,v.required,v.sort_order,v.options::jsonb from platform_modules m cross join (values
('request-code','کد درخواست','text',true,10,'{}'),('contract-code','کد قرارداد','text',true,20,'{}'),('borrower-id','شناسه بدهکار','text',true,30,'{}'),('request-date','تاریخ درخواست','date',true,40,'{}'),('request-type','نوع درخواست','select',true,50,'{"options":["بخشودگی جریمه","بخشودگی سود","امهال مطالبات","تعدیل بدهی","بخشودگی توافقی","سایر"]}'),('principal-amount','اصل بدهی','number',true,60,'{}'),('interest-amount','سود بدهی','number',false,70,'{}'),('penalty-amount','جریمه بدهی','number',false,80,'{}'),('requested-amount','مبلغ درخواستی','number',true,90,'{}'),('approved-amount','مبلغ مصوب','number',false,100,'{}'),('remaining-amount','مانده پس از اجرا','number',false,110,'{}'),('reason','علت درخواست','textarea',true,120,'{}'),('reference','مرجع مستندات','text',false,130,'{}'),('approval-level','سطح تصویب','select',true,140,'{"options":["کارشناس","سرپرست","مدیریت اعتبارات","کمیته اعتباری","مدیریت ارشد"]}'),('approval-status','وضعیت تصویب','select',true,150,'{"options":["در انتظار بررسی","تأیید شده","رد شده","نیازمند اصلاح"]}'),('execution-status','وضعیت اجرا','select',true,160,'{"options":["ثبت اولیه","در حال بررسی","آماده اجرا","اجرا شده","برگشت خورده","لغو شده"]}'),('approved-by','تصویب‌کننده','text',false,170,'{}'),('approved-date','تاریخ تصویب','date',false,180,'{}'),('executed-by','مجری عملیات','text',false,190,'{}'),('executed-date','تاریخ اجرا','date',false,200,'{}'),('accounting-reference','مرجع ثبت مالی','text',false,210,'{}'),('notes','یادداشت','textarea',false,220,'{}')
) v(field_key,title,field_type,required,sort_order,options) where m.code='30-loan-relief' on conflict(module_id,field_key) do update set title=excluded.title,field_type=excluded.field_type,required=excluded.required,sort_order=excluded.sort_order,options=excluded.options;
insert into module_actions(module_id,action_code,title,permission) select m.id,v.action_code,v.title,v.permission from platform_modules m cross join (values ('read','مشاهده','modules:30-loan-relief:read'),('write','ثبت و ویرایش','modules:30-loan-relief:write'),('delete','حذف','modules:30-loan-relief:delete'),('review','بررسی','modules:30-loan-relief:review'),('approve','تصویب','modules:30-loan-relief:approve'),('calculate','محاسبه مانده','modules:30-loan-relief:calculate'),('execute','اجرای مصوبه','modules:30-loan-relief:execute'),('reverse','برگشت اجرا','modules:30-loan-relief:reverse')) v(action_code,title,permission) where m.code='30-loan-relief' on conflict(module_id,action_code) do update set title=excluded.title,permission=excluded.permission;